236→#[cfg(test)]
237→mod tests {
238→    use super::*;
239→
240→    #[test]
241→    fn scrub_removes_secret_env_values() {
242→        let mut env = HashMap::new();
243→        env.insert("API_KEY".to_string(), "super-secret-key-123".to_string());
244→
245→        let input = "Error: failed with key super-secret-key-123";
246→        let scrubbed = scrub_for_telemetry(input, &env);
247→        assert!(
248→            !scrubbed.contains("super-secret-key-123"),
249→            "Secret should be masked: {}",
250→            scrubbed
251→        );
252→    }
253→
254→    #[test]
255→    fn scrub_removes_filesystem_paths() {
256→        let input = "Error: file not found at /Users/brenna/project/src/main.rs";
257→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
258→        assert!(
259→            scrubbed.contains("[PATH]"),
260→            "Path should be replaced: {}",
261→            scrubbed
262→        );
263→        assert!(!scrubbed.contains("/Users/brenna"));
264→    }
265→
266→    #[test]
267→    fn scrub_removes_tokens() {
268→        let input = "Error: auth failed with token ghp_abcdefghijklmnopqrstuvwxyz1234567890";
269→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
270→        assert!(
271→            scrubbed.contains("[REDACTED]"),
272→            "Token should be redacted: {}",
273→            scrubbed
274→        );
275→        assert!(!scrubbed.contains("ghp_"));
276→    }
277→
278→    #[test]
279→    fn scrub_truncates_long_output() {
280→        // Use a word that won't be matched by the hex/token regex
281→        let long_input = "error ".repeat(200);
282→        let scrubbed = scrub_for_telemetry(&long_input, &HashMap::new());
283→        assert!(scrubbed.len() <= MAX_ERROR_LENGTH + 20); // +20 for the truncation message
284→        assert!(scrubbed.ends_with("...[truncated]"));
285→    }
286→
287→    #[test]
288→    fn scrub_preserves_safe_text() {
289→        let input = "Error: bundle install failed with exit code 1";
290→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
291→        assert_eq!(scrubbed, input);
292→    }
293→
294→    #[test]
295→    fn build_report_creates_correct_structure() {
296→        let report = build_report(
297→            "bundler",
298→            "bundle install",
299→            Some(1),
300→            "gem build error",
301→            "retry",
302→            &HashMap::new(),
303→        );
304→
305→        assert_eq!(report.step_name, "bundler");
306→        assert_eq!(report.command_scrubbed, "bundle install");
307→        assert_eq!(report.exit_code, Some(1));
308→        assert_eq!(report.error_scrubbed, "gem build error");
309→        assert_eq!(report.recovery_action, "retry");
310→        assert!(!report.bivvy_version.is_empty());
311→        assert!(!report.platform.is_empty());
312→    }
313→
314→    #[test]
315→    fn telemetry_prompt_not_shown_when_never() {
316→        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
317→        let mut ui = crate::ui::MockUI::new();
318→
319→        let result = prompt_telemetry(&mut ui, &report, Some("never")).unwrap();
320→        assert_eq!(result, TelemetryConsent::Never);
321→        // No prompt should have been shown
322→        assert!(ui.prompts_shown().is_empty());
323→    }
324→
325→    #[test]
326→    fn telemetry_auto_sends_when_always() {
327→        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
328→        let mut ui = crate::ui::MockUI::new();
329→
330→        let result = prompt_telemetry(&mut ui, &report, Some("always")).unwrap();
331→        assert_eq!(result, TelemetryConsent::Always);
332→        assert!(ui.prompts_shown().is_empty());
333→    }
334→
335→    #[test]
336→    fn telemetry_saves_report_to_disk() {
337→        let temp = tempfile::TempDir::new().unwrap();
338→        let report = build_report(
339→            "bundler",
340→            "bundle install",
341→            Some(1),
342→            "build error",
343→            "retry",
344→            &HashMap::new(),
345→        );
346→
347→        let path = save_report_to(&report, temp.path()).unwrap();
348→        assert!(path.exists());
349→
350→        let content = std::fs::read_to_string(&path).unwrap();
351→        assert!(content.contains("bundler"));
352→        assert!(content.contains("bundle install"));
353→    }
354→
355→    #[test]
356→    fn failure_report_contains_no_paths() {
357→        let mut env = HashMap::new();
358→        env.insert("HOME".to_string(), "/Users/brenna".to_string());
359→
360→        let report = build_report(
361→            "test",
362→            "make build",
363→            Some(1),
364→            "Error at /Users/brenna/project/main.c:42",
365→            "retry",
366→            &env,
367→        );
368→
369→        assert!(!report.error_scrubbed.contains("/Users/brenna"));
370→        assert!(report.error_scrubbed.contains("[PATH]"));
371→    }
372→
373→    #[test]
374→    fn telemetry_prompt_returns_send() {
375→        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
376→        let mut ui = crate::ui::MockUI::new();
377→        ui.set_interactive(true);
378→        ui.set_prompt_response("telemetry_failure", "send");
379→
380→        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
381→        assert_eq!(result, TelemetryConsent::Send);
382→    }
383→
384→    #[test]
385→    fn telemetry_prompt_returns_no_thanks() {
386→        let report = build_report("test", "echo test", Some(0), "", "retry", &HashMap::new());
387→        let mut ui = crate::ui::MockUI::new();
388→        ui.set_interactive(true);
389→        ui.set_prompt_response("telemetry_failure", "no_thanks");
390→
391→        let result = prompt_telemetry(&mut ui, &report, None).unwrap();
392→        assert_eq!(result, TelemetryConsent::NoThanks);
393→    }
394→
395→    #[test]
396→    fn scrub_removes_sk_tokens() {
397→        let input = "key: sk-abcdefghij1234567890abcdef";
398→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
399→        assert!(scrubbed.contains("[REDACTED]"));
400→        assert!(!scrubbed.contains("sk-"));
401→    }
402→
403→    #[test]
404→    fn scrub_removes_home_paths() {
405→        let input = "Error at /home/user/project/file.rs:42";
406→        let scrubbed = scrub_for_telemetry(input, &HashMap::new());
407→        assert!(scrubbed.contains("[PATH]"));
408→        assert!(!scrubbed.contains("/home/user"));
409→    }
