        let temp = tempfile::TempDir::new().unwrap();

        let r1 = build_report("step1", "cmd1", Some(1), "e1", "retry", &HashMap::new());
        let r2 = build_report("step2", "cmd2", Some(2), "e2", "fix", &HashMap::new());

        let p1 = save_report_to(&r1, temp.path()).unwrap();
        // Small delay to ensure different timestamps
        std::thread::sleep(std::time::Duration::from_millis(1100));
        let p2 = save_report_to(&r2, temp.path()).unwrap();

        assert_ne!(p1, p2);
        assert!(p1.exists());
        assert!(p2.exists());

        let files: Vec<_> = std::fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();
        assert_eq!(files.len(), 2);
    }
