#[test]
fn reports_dir_ends_with_expected_segments() {
    let dir = reports_dir();
    let components: Vec<_> = dir.components().collect();
    let last_two: Vec<_> = components.iter().rev().take(2).collect();

    assert_eq!(
        dir.file_name().unwrap().to_str().unwrap(),
        "failure-reports"
    );
    assert!(dir.parent().unwrap().file_name().unwrap().to_str().unwrap() == ".bivvy");
}

